    """Open a connection to the SQLite database at ``path``."""
    return sqlite3.connect(path)


def _fetch_one(conn: sqlite3.Connection, query: str, value: str) -> Optional[UserRow]:
    """Run a single-parameter ``query`` and return the first row, or ``None``."""
    with closing(conn.cursor()) as cursor:
        cursor.execute(query, (value,))
        return cursor.fetchone()


def find_user(conn: sqlite3.Connection, username: str) -> Optional[UserRow]:
    """Return the ``(id, email)`` row for ``username``, or ``None`` if not found."""
    return _fetch_one(conn, FIND_USER_QUERY, username)


def find_user_by_email(conn: sqlite3.Connection, email: str) -> Optional[UserRow]:
    """Return the ``(id, email)`` row for ``email``, or ``None`` if not found."""
    return _fetch_one(conn, FIND_USER_BY_EMAIL_QUERY, email)


