import sqlite3
import threading
from typing import Dict, Optional, Tuple

DEFAULT_DB_PATH = "users.db"

# LIMIT 1 lets SQLite stop scanning as soon as a match is found.
FIND_USER_QUERY = "SELECT id, email FROM users WHERE name = ? LIMIT 1"
FIND_USER_BY_EMAIL_QUERY = "SELECT id, email FROM users WHERE email = ? LIMIT 1"

# Indexes turn the lookups above from full table scans into index seeks.
_INDEX_STATEMENTS = (
    "CREATE INDEX IF NOT EXISTS idx_users_name ON users(name)",
    "CREATE INDEX IF NOT EXISTS idx_users_email ON users(email)",
)

UserRow = Tuple[int, str]

# sqlite3 connections may not be shared across threads by default, so
# connections are cached per thread and per database path.
_local = threading.local()


def get_connection(path: str = DEFAULT_DB_PATH) -> sqlite3.Connection:
    """Open a new connection to the SQLite database at ``path``."""
    return sqlite3.connect(path)


def ensure_indexes(conn: sqlite3.Connection) -> None:
    """Create lookup indexes on ``users`` if the table exists and they are missing."""
    try:
        with conn:
            for statement in _INDEX_STATEMENTS:
                conn.execute(statement)
    except sqlite3.OperationalError:
        # Table missing or database read-only: lookups still work, just unindexed.
        pass


def _get_cached_connection(path: str = DEFAULT_DB_PATH) -> sqlite3.Connection:
    """Return a reusable connection for the current thread, creating it on first use."""
    cache: Optional[Dict[str, sqlite3.Connection]] = getattr(_local, "connections", None)
    if cache is None:
        cache = _local.connections = {}

    conn = cache.get(path)
    if conn is None:
        conn = get_connection(path)
        ensure_indexes(conn)
        cache[path] = conn
    return conn


def close_cached_connections() -> None:
    """Close all connections cached for the current thread."""
    cache: Optional[Dict[str, sqlite3.Connection]] = getattr(_local, "connections", None)
    if not cache:
        return
    for conn in cache.values():
        conn.close()
    cache.clear()


