    return _fetch_one(conn, FIND_USER_QUERY, username)


def find_user_by_email(conn: sqlite3.Connection, email: str) -> Optional[UserRow]:
    """Return the ``(id, email)`` row for ``email``, or ``None`` if not found."""
    return _fetch_one(conn, FIND_USER_BY_EMAIL_QUERY, email)


